#include <windows.h>

int main() {
    constexpr SIZE_T size = 4096;
    void* region = VirtualAlloc(nullptr, size, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
    if (region == nullptr) {
        return static_cast<int>(GetLastError());
    }

