#include <windows.h>
#include <stdio.h>

int main() {
    char temp_path[MAX_PATH] = {};
    char file_path[MAX_PATH] = {};
    GetTempPathA(MAX_PATH, temp_path);
    GetTempFileNameA(temp_path, "nte", 0, file_path);

    HANDLE file = CreateFileA(file_path, GENERIC_READ | GENERIC_WRITE, 0,
        nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (file == INVALID_HANDLE_VALUE) {
        return 1;
    }

    const char text[] = "example";
    DWORD written = 0;
    WriteFile(file, text, sizeof(text) - 1, &written, nullptr);

    HANDLE mapping = CreateFileMappingA(file, nullptr, PAGE_READWRITE, 0, 0,
        nullptr);
    if (mapping != nullptr) {
        void* view = MapViewOfFile(mapping, FILE_MAP_READ, 0, 0, 0);
        if (view != nullptr) {
            printf("Mapped view: %.7s\n", static_cast<char*>(view));
            UnmapViewOfFile(view);
        }
        CloseHandle(mapping);
    }

    CloseHandle(file);
    DeleteFileA(file_path);
    return 0;
}

