#include <windows.h>
#include <stdio.h>

static DWORD WINAPI Worker(LPVOID) {
    return 0;
}

int main() {
    // Using the current process makes this equivalent to CreateThread.
    HANDLE thread = CreateRemoteThread(GetCurrentProcess(), nullptr, 0,
        Worker, nullptr, 0, nullptr);
    if (thread == nullptr) {
        return 1;
    }

    WaitForSingleObject(thread, 5000);
    CloseHandle(thread);
    return 0;
}

