#include <windows.h>
#include <stdio.h>

static void CALLBACK Apc(ULONG_PTR data) {
    printf("APC ran with value %llu\n",
        static_cast<unsigned long long>(data));
}

int main() {
    if (QueueUserAPC(Apc, GetCurrentThread(), 1) == 0) {
        return 1;
    }

    // SleepEx with alertable TRUE allows the queued APC to run.
    SleepEx(0, TRUE);
    return 0;
}

